        private void RecordLastAlert(string text, SMDWin.Services.NotifSeverity severity = SMDWin.Services.NotifSeverity.Warning)
        {
            _lastAlertText = $"{DateTime.Now:HH:mm} — {text}";
            SMDWin.Services.NotificationCenter.Add(SMDWin.Services.NotifCategory.Temperature, severity, text);
        }

        internal void DismissLastAlert_Click(object sender, RoutedEventArgs e)
        {
            _lastAlertText = null;
            _badgeTempActive = false;
            _lastTempBadgeLevel = 0;
            _lastTempBadgeCount = 0;
            UpdateSidebarBadge("Temp", 0, "");
            if (LastAlertBanner != null) LastAlertBanner.Visibility = Visibility.Collapsed;
        }
        private DateTime _lastThrottleNotif   = DateTime.MinValue;
        private SMDWin.Services.ThrottleReason _throttleCandidateReason = SMDWin.Services.ThrottleReason.None;
        private int      _throttleConsecutiveTicks = 0;
        private const int ThrottleConfirmTicks = 3;
        private DateTime _lastSmartNotif      = DateTime.MinValue;
        private DateTime _lastDiskSpaceNotif  = DateTime.MinValue;
        private const int BalloonCooldownSeconds = 120;  // temp/cpu — max once per 2 min
        private const int SlowNotifCooldownSec   = 600;  // SMART/disk/throttle — once per 10 min
        private const int NetNotifCooldownSec    = 300;  // network — once per 5 min
        // CPU high usage: alert only if it stays above the threshold for 60 s continuously
        private DateTime? _cpuHighSince = null;
        private const int CpuHighAlertDelaySec = 60;
        // Network baseline (established after 30s) for unusual activity detection
        private const int NetBaselineSamples = 30;       // ~60s at 2s tick — longer baseline
        private const float NetSpikeMultiplier = 15f;    // 15× baseline = unusual (less sensitive)

        private void UpdateTrayIconWithTemp(float? cpuTemp, float? gpuTemp)
        {
            if (_notifyIcon == null) return;

            // Throttle to every 5 ticks — icon stays static (app logo), only tooltip changes
            _trayTickCount++;
            if (_trayTickCount % 5 != 1) return;

            var sb = new System.Text.StringBuilder("SMD Win");
            if (cpuTemp.HasValue && cpuTemp > 0)
                sb.Append($"\nCPU  {TempUnit.Fmt(cpuTemp.Value)}  {TempBar(cpuTemp.Value)}");
            if (gpuTemp.HasValue && gpuTemp > 0)
                sb.Append($"\nGPU  {TempUnit.Fmt(gpuTemp.Value)}  {TempBar(gpuTemp.Value)}");

            string tip = sb.ToString();
            _notifyIcon.Text = tip.Length > 63 ? tip[..63] : tip;

            // ── Balloon tip notifications (if enabled) ──────────────────────
            if (!SettingsService.Current.EnableNotifications) return;
            if ((DateTime.Now - _lastBalloonTime).TotalSeconds < BalloonCooldownSeconds) return;

            string? alertTitle = null;
            string? alertMsg = null;
            Forms.ToolTipIcon alertIcon = Forms.ToolTipIcon.Warning;

            float cpuThreshold = SettingsService.Current.CpuTempAlertThreshold > 0
                                 ? SettingsService.Current.CpuTempAlertThreshold : 85f;
            float gpuThreshold = SettingsService.Current.GpuTempAlertThreshold > 0
                                 ? SettingsService.Current.GpuTempAlertThreshold : 85f;
            float cpuUsageThreshold = SettingsService.Current.CpuUsageAlertThreshold > 0
                                      ? SettingsService.Current.CpuUsageAlertThreshold : 95f;

            if (cpuTemp.HasValue && cpuTemp >= cpuThreshold)
            {
                alertTitle = _LS("Notif", "CpuTempAlertTitle");
                alertMsg = string.Format(_LS("Notif", "CpuTempAlertMsg"), cpuTemp.Value.ToString("F0"));
                if (cpuTemp >= 95) alertIcon = Forms.ToolTipIcon.Error;
            }
            else if (gpuTemp.HasValue && gpuTemp >= gpuThreshold)
            {
                alertTitle = _LS("Notif", "GpuTempAlertTitle");
                alertMsg = string.Format(_LS("Notif", "GpuTempAlertMsg"), gpuTemp.Value.ToString("F0"));
                if (gpuTemp >= 95) alertIcon = Forms.ToolTipIcon.Error;
            }

            if (alertTitle == null)
            {
                bool stressRunningForAlert = _cpuStress.Running || _gpuStress.IsRunning;
                if (stressRunningForAlert)
                {
                    _cpuHighSince = null;
                }
                else
                {
                    float cpuPct = GetCpuUsagePct();
                    if (cpuPct >= cpuUsageThreshold)
                    {
                        if (_cpuHighSince == null) _cpuHighSince = DateTime.UtcNow;
                        else if ((DateTime.UtcNow - _cpuHighSince.Value).TotalSeconds >= CpuHighAlertDelaySec)
                        {
                            alertTitle = _LS("Notif", "CpuLoadAlertTitle");
                            alertMsg = string.Format(_LS("Notif", "CpuLoadAlertMsg"), cpuPct.ToString("F0"), CpuHighAlertDelaySec);
                        }
                    }
                    else
                    {
                        _cpuHighSince = null; // reset if it drops below the threshold
                    }
                }
            }

            if (alertTitle != null && alertMsg != null)
            {
                try
                {
                    _notifyIcon.ShowBalloonTip(5000, alertTitle, alertMsg, alertIcon);
                    _lastBalloonTime = DateTime.Now;
                }
                catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.unknown"); }
            }
        }

        /// <summary>Send a Windows balloon notification with per-type cooldown.</summary>
        private void SendWindowsNotif(string title, string msg,
            ref DateTime lastSent, int cooldownSec,
            Forms.ToolTipIcon icon = Forms.ToolTipIcon.Warning)
        {
            if (_notifyIcon == null) return;
            if (!SettingsService.Current.EnableNotifications) return;
            if ((DateTime.Now - lastSent).TotalSeconds < cooldownSec) return;
            try
            {
                _notifyIcon.ShowBalloonTip(6000, title, msg, icon);
                lastSent = DateTime.Now;
            }
            catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.SendWindowsNotif"); }
        }

        /// <summary>Check and fire throttling notification.</summary>
        internal void CheckThrottleNotif(bool isThrottled, string reason)
        {
            if (!isThrottled) return;
            string msg = string.Format(_LS("Notif", "ThrottleMsg"), reason);
            SendWindowsNotif(_LS("Notif", "ThrottleTitle"), msg, ref _lastThrottleNotif, SlowNotifCooldownSec);
            SMDWin.Services.NotificationCenter.Add(
                SMDWin.Services.NotifCategory.Throttle, SMDWin.Services.NotifSeverity.Warning, msg);
        }

        /// <summary>Check SMART health and fire notification if needed.</summary>
        internal void CheckSmartNotif(System.Collections.Generic.IEnumerable<DiskHealthEntry> disks)
        {
            foreach (var d in disks)
            {
                if (d.HealthPercent < 80)
                {
                    string msg = string.Format(_LS("Notif", "SmartHealthMsg"),
                        d.Model.Split(' ').FirstOrDefault() ?? "Drive", d.HealthPercent);
                    var sev = d.HealthPercent < 50 ? Forms.ToolTipIcon.Error : Forms.ToolTipIcon.Warning;
                    SendWindowsNotif(_LS("Notif", "SmartHealthTitle"), msg, ref _lastSmartNotif, SlowNotifCooldownSec, sev);
                    SMDWin.Services.NotificationCenter.Add(SMDWin.Services.NotifCategory.Disk,
                        d.HealthPercent < 50 ? SMDWin.Services.NotifSeverity.Critical : SMDWin.Services.NotifSeverity.Warning, msg);
                    return;
                }
                if (d.Status?.Contains("Realloc", StringComparison.OrdinalIgnoreCase) == true
                    || d.Status?.Contains("SMART Warning", StringComparison.OrdinalIgnoreCase) == true)
                {
                    string msg = string.Format(_LS("Notif", "SmartWarnMsg"),
                        d.Model.Split(' ').FirstOrDefault() ?? "Drive");
                    SendWindowsNotif(_LS("Notif", "SmartWarnTitle"), msg, ref _lastSmartNotif, SlowNotifCooldownSec,
                        Forms.ToolTipIcon.Error);
                    SMDWin.Services.NotificationCenter.Add(
                        SMDWin.Services.NotifCategory.Disk, SMDWin.Services.NotifSeverity.Critical, msg);
                    return;
                }
            }
        }

        /// <summary>Check free space on ALL fixed drives and fire notification if
        /// critically low.</summary>
        internal async void CheckDiskSpaceNotif()
        {
            try
            {
                // drives are read in the background: an external disk that spins up slowly no longer blocks the window
                foreach (var drive in await SMDWin.Services.DriveSnapshot.ReadyDrivesAsync())
                {
                    if (drive.Type != System.IO.DriveType.Fixed) continue;
                    double freeGB = drive.FreeBytes / 1_073_741_824.0;
                    if (freeGB >= 2.0) continue;

                    string msg = string.Format(_LS("Notif", "DiskSpaceMsg"), drive.Root, freeGB.ToString("F1"));
                    SendWindowsNotif(
                        _LS("Notif", "DiskSpaceTitle"), msg,
                        ref _lastDiskSpaceNotif, SlowNotifCooldownSec,
                        Forms.ToolTipIcon.Error);
                    SMDWin.Services.NotificationCenter.Add(
                        SMDWin.Services.NotifCategory.Disk, SMDWin.Services.NotifSeverity.Critical,
                        msg);
                }
            }
            catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.CheckDiskSpaceNotif"); }
        }


        private static string TempBar(float t)
        {
            int f = Math.Clamp((int)Math.Round(t / 10f), 0, 10);
            return (t >= 85 ? "" : t >= 70 ? "" : "") + $" {TempUnit.Fmt(t)}";
        }

        [System.Runtime.InteropServices.DllImport("user32.dll", SetLastError = true)]
        private static extern bool DestroyIcon(IntPtr hIcon);

        private float GetCpuUsagePct() => _cachedCpuPct;
        // Returns 0 while perf counters are warming up (first read always returns 0 from Windows)
        // Returns -1 only if GPU Engine category is unavailable (no GPU or driver issue)
        private float GetGpuUsagePct() => _cachedGpuPct < 0 && _gpuCountersInitialized && (_gpuCounters == null || _gpuCounters.Count == 0)
            ? -1f   // truly unavailable — no GPU Engine counters
            : Math.Max(0f, _cachedGpuPct);  // treat -1 (not-yet-read) as 0%
    }
